import crypto from 'node:crypto';
import fs from 'node:fs/promises';
import path from 'node:path';
import { config } from '../config.js';

// Reads a multipart request: returns { fields, file }
export async function readMultipart(request, { maxBytes = config.maxReceiptBytes } = {}) {
  const fields = {};
  let file = null;
  const parts = request.parts({ limits: { fileSize: maxBytes, files: 1, fields: 30 } });
  for await (const part of parts) {
    if (part.type === 'file') {
      const buffer = await part.toBuffer();
      if (part.file.truncated) {
        const err = new Error('file_too_large');
        err.statusCode = 413;
        throw err;
      }
      if (buffer.length) file = { buffer, filename: part.filename, mimetype: part.mimetype };
    } else {
      fields[part.fieldname] = part.value;
    }
  }
  return { fields, file };
}

// Checks the REAL file type from its first bytes (not the file name)
export function detectImage(buf, { allowWebp = false } = {}) {
  if (buf.length > 12) {
    if (buf[0] === 0x89 && buf[1] === 0x50 && buf[2] === 0x4e && buf[3] === 0x47) return 'png';
    if (buf[0] === 0xff && buf[1] === 0xd8 && buf[2] === 0xff) return 'jpg';
    if (
      allowWebp &&
      buf.toString('ascii', 0, 4) === 'RIFF' &&
      buf.toString('ascii', 8, 12) === 'WEBP'
    )
      return 'webp';
  }
  return null;
}

// folder: 'receipts' | 'cars'. Returns the public URL path.
export async function saveImage(file, folder, opts) {
  const ext = detectImage(file.buffer, opts);
  if (!ext) {
    const err = new Error('invalid_image');
    err.statusCode = 400;
    throw err;
  }
  const name = `${crypto.randomBytes(16).toString('hex')}.${ext}`;
  await fs.mkdir(path.join(config.uploadDir, folder), { recursive: true });
  await fs.writeFile(path.join(config.uploadDir, folder, name), file.buffer);
  return `/uploads/${folder}/${name}`;
}

export async function deleteUpload(urlPath) {
  if (!urlPath?.startsWith('/uploads/')) return;
  const rel = urlPath.replace('/uploads/', '');
  if (rel.includes('..')) return;
  await fs.rm(path.join(config.uploadDir, rel), { force: true });
}
